DROP_KEY = {'—', 'G1', 'G2', 'G3', 'Не свободный код состояния'}
BOILER = {'G1', 'G2', 'G3', 'Источник/ЦД по смыслу поля. Не смешивать effective и recorded time', '—'}

def codes(s):
    return re.sub(r'^(Предлагаемые коды|Предложение)\s*:?\s*', 'Коды: ', s)

def conv(fl):
    t = [p for p in str(fl['type']).split('; ') if not p.startswith('Пример:')]
    out = dict(name=fl['name'], title=fl.get('title', ''), type=t[0], required='; '.join(t[1:]) or '')
    kparts, notes = [], []
    for p in str(fl['key']).split('; '):
        p = p.strip()
        if p in DROP_KEY or re.match(r'^Ключ \w+$', p): continue
        p = re.sub(r'^FK → (\w+)\.id', r'FK → \1', codes(p))
        if p.startswith(('PK', 'FK', 'U1', 'U2', 'U ', 'Коды:', 'CD-D', 'MODEL-Q', 'OD-')): kparts.append(p)
        elif p == 'UTC + исходная зона': notes.append('UTC и исходная зона')
        else: notes.append(p)
    src = str(fl.get('source', '')).strip()
    if src not in BOILER:
        src = re.sub(r'^Источник/расчёт по полю\.\s*', '', src)
        src = re.sub(r'\.?\s*G[123]$', '', src)
        src = src.replace('Переходы только по условиям раздела жизненного цикла', 'переходы — STATES')
        src = src.replace('КЭ1-04 § STATES', 'STATES').replace('КЭ1-04 REV-R11', 'REV-R11')
        src = src.replace('Требование ключа действует и для Э1', 'Требование ключа действует всегда')
        if src: notes.append(src)
    out['key'] = '; '.join(kparts)
    note = '; '.join(n.rstrip('.') for n in notes)
    for a, b in FIX:
        note = note.replace(a, b)
    out['note'] = note
    return out

for f in sorted(glob.glob(f'{SRC}/*.yaml')):
    y = yaml.safe_load(open(f, encoding='utf-8'))
    if not any('title' in fl for fl in y['fields']): continue           # ручные файлы K01/K03/K05/K23/K24 — отдельно
    fields, extra = [], {}
    for fl in y['fields']:
        if fl['name'] in ('is_test',): continue
        m = re.match(r'^(\w+) \(дополнение\)$', fl['name'])
        if m: extra[m.group(1)] = fl; continue
        if ', ' in fl['name']:
            for n in fl['name'].split(', '):
                c = conv(dict(fl, name=n)); c['title'] = {'instrument_id': 'Выпуск', 'custody_link_id': 'Место учёта'}.get(n, c['title'])
                c['key'] = 'FK → ' + {'instrument_id': 'instrument_version', 'custody_link_id': 'custody_link'}[n]; fields.append(c)
            continue
        fields.append(conv(fl))
    for base, fl in extra.items():
        for c in fields:
            if c['name'] == base:
                c['key'] = (c['key'] + '; ' if c['key'] else '') + codes(fl['key']).lstrip('+ ').strip()
                c['note'] = (c['note'] + '; ' if c['note'] else '') + str(fl['source']).replace('КЭ1-04 ', '')
    for c in fields:
        c.update(PATCH.get((y['entity'], c['name']), {}))
        tr = TRACE.get((y['entity'], c['name']))
        if tr: c['trace'] = tr
    fields += ADD.get(y['entity'], [])
    origin = re.findall(r'(Связанные UC: [^.]+\.|Опора[^.]*: [^\n]+)', y.get('note') or '')
    obj = dict(id=y['id'], entity=y['entity'], title=re.sub(r'\s*\(цель, профиль РЦД\)', '', y['title']), note=NOTES[y['id']],
               origin='КЭ1-03 § ' + y['id'] + ('; ' + ' '.join(o.strip() for o in origin) if origin else ''), fields=fields)
    if y.get('links'): obj['links'] = [dict(l, link=str(l['link']).replace('обратно 2 в CREDIT Э1', 'обратно 2 при зачислении')) for l in y['links']]
    with open(f'{DST}/{os.path.basename(f)}', 'w', encoding='utf-8') as fo:
        yaml.dump(obj, fo, allow_unicode=True, sort_keys=False, width=1000)
    print(y['id'], y['entity'], len(fields))
